import java.nio.file.*;import java.util.*;import org.json.*;
public final class PlaymogoBothHostsCheck {
 public static void main(String[] args)throws Exception{JSONObject f=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8")).getJSONArray("fixtures").getJSONObject(0);NativeHttp.CURRENT.set(new NativeHttp.Session(30000));try{DozaCatalog.Located located=new DozaCatalog().locate(f.getJSONObject("data"));if(located==null||!located.pageUrl.equals(f.getString("page")))throw new AssertionError("Episode discovery");Set<String> resolved=new HashSet<>();for(NativeCatalog.Candidate candidate:DozaCatalog.players(located.page,located.pageUrl)){ResolvedStream stream=RoDubbedProvider.resolve(candidate);Object link=RoDubbedProvider.makeLink(stream);String format=link.getClass().getMethod("getType").invoke(link).toString();if(!stream.site.equals("DozaAnimata"))throw new AssertionError("Wrong site attribution");System.out.println("PASS "+stream.host+" "+format+" DozaAnimata");resolved.add(stream.host);}if(resolved.size()!=2||!resolved.contains("Playmogo")||!resolved.contains("Vidmoly"))throw new AssertionError("Expected both servers");System.out.println("PASS official v7 both Miraculos servers");}finally{NativeHttp.session().stop();}System.exit(0);}
}
